class Solution:
    def maxResult(self, nums: List[int], k: int) -> int:
        dq = deque()
        for i, num in enumerate(nums):
            while dq and dq[0][0] < i - k:
                dq.popleft()

            score = num + (dq[0][1] if dq else 0)

            while dq and dq[-1][1] <= score:
                dq.pop()
            dq.append((i, score))

        return score

