import java.io.*;
import java.util.*;

class Solution {
    public int maxResult(int[] nums, int k) {
        int cap = k + 1;
        int[] dqIndex = new int[cap];
        long[] dqScore = new long[cap];
        int head = 0, tail = 0;
        long answer = 0;

        for (int i = 0; i < nums.length; i++) {
            while (head < tail && dqIndex[head % cap] < i - k) head++;

            long score = nums[i] + (head == tail ? 0L : dqScore[head % cap]);

            while (head < tail && dqScore[(tail - 1) % cap] <= score) tail--;

            dqIndex[tail % cap] = i;
            dqScore[tail % cap] = score;
            tail++;
            answer = score;
        }

        return (int) answer;
    }
}

