            ++pos;
    }

    string nextToken() {
        skipWS();
        if (pos >= s.size()) return "";
        size_t start = pos;

        if (s[pos] == '[') {
            int depth = 0;
            do {
                char c = s[pos++];
                if (c == '[') ++depth;
                else if (c == ']') --depth;
            } while (pos < s.size() && depth > 0);
        } else {
            while (pos < s.size() && s[pos] != ',' && s[pos] != ']') ++pos;
        }
        return s.substr(start, pos - start);
    }
};

vector<int> parseIntArray(Tok& tok) {
    string arr = tok.nextToken();
    if (arr == "[]") return {};

    string inner = arr.substr(1, arr.size() - 2);
    vector<int> out;
    size_t start = 0;
    while (start < inner.size()) {
        size_t comma = inner.find(',', start);
        string part = inner.substr(start, comma == string::npos ? string::npos : comma - start);
        out.push_back(stoi(part));
        if (comma == string::npos) break;
        start = comma + 1;
    }
    return out;
}

class Solution {
public:
    int maxResult(vector<int>& nums, int k) {
        deque<pair<int, long long>> dq;

        for (int i = 0; i < (int)nums.size(); ++i) {
            while (!dq.empty() && dq.front().first < i - k) dq.pop_front();

            long long score = nums[i] + (dq.empty() ? 0LL : dq.front().second);

            while (!dq.empty() && dq.back().second <= score) dq.pop_back();
            dq.push_back({i, score});
        }

        return (int)dq.back().second;
    }
};

