typedef struct {
    char* s;
    int pos;
    int len;
} Tok;

static void skipWS(Tok* t) {
    while (t->pos < t->len &&
           (t->s[t->pos] == ' ' || t->s[t->pos] == ',' ||
            t->s[t->pos] == '\t' || t->s[t->pos] == '\n' ||
            t->s[t->pos] == '\r')) {
        t->pos++;
    }
}

static char* nextToken(Tok* t) {
    skipWS(t);
    if (t->pos >= t->len) return NULL;
    int start = t->pos;

    if (t->s[t->pos] == '[') {
        int depth = 0;
        while (t->pos < t->len) {
            char c = t->s[t->pos++];
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) break;
            }
        }
    } else {
        while (t->pos < t->len && t->s[t->pos] != ',' &&
               t->s[t->pos] != ']' && t->s[t->pos] != '[') {
            t->pos++;
        }
    }

    int token_len = t->pos - start;
    char* token = (char*)malloc((size_t)token_len + 1);
    memcpy(token, t->s + start, (size_t)token_len);
    token[token_len] = '\0';
    return token;
}

static int parse_int(Tok* t) {
    char* tok = nextToken(t);
    if (!tok) return 0;
    int val = atoi(tok);
    free(tok);
    return val;
}

static int* parse_int_array(Tok* t, int* out_size) {
    char* tok = nextToken(t);
    if (!tok || strcmp(tok, "[]") == 0) {
        if (tok) free(tok);
        *out_size = 0;
        return NULL;
    }

    int len = (int)strlen(tok);
    char* inner = (char*)malloc((size_t)len - 1);
    memcpy(inner, tok + 1, (size_t)len - 2);
    inner[len - 2] = '\0';
    free(tok);

    int size = 1;
    for (int i = 0; inner[i]; i++) {
        if (inner[i] == ',') size++;
    }

    int* arr = (int*)malloc((size_t)size * sizeof(int));
    Tok t2 = {inner, 0, (int)strlen(inner)};
    for (int i = 0; i < size; i++) arr[i] = parse_int(&t2);

    free(inner);
    *out_size = size;
    return arr;
}

int maxResult(int* nums, int numsSize, int k) {
    int cap = k + 1;
    int* dqIndex = (int*)malloc((size_t)cap * sizeof(int));
    long long* dqScore = (long long*)malloc((size_t)cap * sizeof(long long));
    int head = 0, tail = 0;
    long long answer = 0;

    for (int i = 0; i < numsSize; i++) {
        while (head < tail && dqIndex[head % cap] < i - k) head++;

        long long score = nums[i] + (head == tail ? 0LL : dqScore[head % cap]);

